public Vector3 WorldToViewportCoordinates(Vector3 point, Camera camera)
{
    if (camera.orthographic)
    {
        point = camera.WorldToViewportPoint(point);
    }
    else
    {
        point = RectTransformUtility.WorldToScreenPoint(null, point);
        point.z = 0.5f;
        point = camera.ScreenToViewportPoint(point);
    }

    return point;
}
```

