public class ProcessFilter
{
    public IEnumerable<Process> FilterProcesses(IEnumerable<Process> processes, Status messagingStatus, Status processingStatus, ComparisonOperator @operator)
    {
        if (@operator == ComparisonOperator.Equal)
        {
            return processes
                .Where(p => p.MessagingSteps.Any(ms => ms.Status == messagingStatus) || p.ProcessingSteps.Any(ps => ps.Status == processingStatus));
        }
        else if (@operator == ComparisonOperator.NotEqual)
        {
            return processes
                .Where(p => p.MessagingSteps.All(ms => ms.Status != messagingStatus) && p.ProcessingSteps.All(ps => ps.Status != processingStatus));
        }
        else
        {
            throw new ArgumentException("Invalid comparison operator");
        }
    }
}
