    {
        void Handle(TCommand command);
    }

    // Implement the command processor
    public class CommandProcessor
    {
        private readonly Dictionary<Type, object> _handlers = new Dictionary<Type, object>();

        // Register a command handler for a specific command type
        public void RegisterHandler<TCommand>(ICommandHandler<TCommand> handler) where TCommand : ICommand
        {
            _handlers[typeof(TCommand)] = handler;
        }

        // Process a command by executing the appropriate handler
        public void ProcessCommand<TCommand>(TCommand command) where TCommand : ICommand
        {
            if (_handlers.TryGetValue(typeof(TCommand), out var handler))
            {
                ((ICommandHandler<TCommand>)handler).Handle(command);
            }
            else
            {
                throw new InvalidOperationException($"No handler registered for command type {typeof(TCommand)}");
            }
        }
    }

    // Define a sample command
    public class SampleCommand : ICommand
    {
        public string Id { get; }

        public SampleCommand(string id)
        {
            Id = id;
        }
    }

    // Implement a handler for the sample command
    public class SampleCommandHandler : ICommandHandler<SampleCommand>
    {
        public void Handle(SampleCommand command)
        {
            Console.WriteLine($"Handling SampleCommand with Id: {command.Id}");
        }
    }

